      // The mesh: a pale checker, brighter in the day
      for (let yy = 17; yy < 33; yy++) for (let xx = 209; xx < 219; xx++) if ((xx + yy) % 2 === 0) dot(xx + dx, yy, mesh, isNight ? 0.2 : 0.3);
      // Leaf shadows sway across the mesh now and then
