      for (const [lx, ly] of [[211, 21], [212, 22], [211, 23], [215, 28], [216, 27], [216, 29]]) dot(lx + dx + sway, ly, 0x2f6a3a, 0.65);
      // The wooden frame, with a kick board and a handle
