    /**
     * Kitchen doors: a pair of stainless swing doors with a round porthole window in each and steel kick plates. Someone going
     * through pushes them wide; once they're past, they flap to and fro, less each time, and settle shut.
     */
    function drawKitchendoorDoor(open) {
      const steel = 0xc8ccd2, steelLight = 0xe4e8ec, steelDark = 0x8a9098, glass = 0xdff0f6;
      fill(207, 15, 14, 25, PALETTE.doorway);
      fill(207, 37, 14, 3, 0x6a6458, 0.5);
      if (open) office.kitchenPassedAt = now;
      const since = now - (office.kitchenPassedAt ?? -99);
      const swing = open ? 1 : since < SWING_FOR ? Math.exp(-since * 1.3) * Math.cos(since * 7.5) : 0;
      const width = Math.max(1, Math.round(7 * (1 - Math.abs(swing) * 0.85)));
      const tone = (c) => (swing < 0 ? shaded(c, 0.85) : c);
      for (const side of [-1, 1]) {
        const lx = side < 0 ? 207 : 221 - width;
        fill(lx, 15, width, 25, tone(steel)); fill(lx, 15, width, 1, tone(steelLight)); fill(side < 0 ? lx : lx + width - 1, 15, 1, 25, tone(steelDark));
        fill(lx, 34, width, 5, tone(steelDark)); fill(lx, 34, width, 1, tone(steelLight));
        if (width >= 5) {
          const cx = lx + Math.floor(width / 2);
          disc(cx, 22, 2.2, tone(0x6e727c)); disc(cx, 22, 1.6, glass, 0.55); dot(cx - 1, 21, WHITE, 0.8);
        }
      }
    }

