      const draw = () => { line(x0, y0, x1, y1, colour); glowAt((x0 + x1) / 2, (y0 + y1) / 2, Math.abs(x1 - x0) / 2 + 3, Math.abs(y1 - y0) / 2 + 3, colour, 0.16); line(x0, y0, x1, y1, shaded(colour, 1.6), 0.7); };
