    /** Small marks drawn from rows of dots: a heart, and the script B (brand nod: Barbie). */
    const G1_MARKS = {
      heart: ['.XX.XX.', 'XXXXXXX', 'XXXXXXX', '.XXXXX.', '..XXX..', '...X...'],
      smallheart: ['X.X', 'XXX', '.X.'],
      b: ['XXX.', 'X..X', 'XXX.', 'X..X', 'X..X', 'XXX.'],
    };
    function g1Mark(kind, x0, y0, colour, alpha = 1) {
      G1_MARKS[kind].forEach((row, r) => { for (let c = 0; c < row.length; c++) if (row[c] === 'X') dot(x0 + c, y0 + r, colour, alpha); });
    }
