    /** The first Apple pack's colours: modern white, aluminium silver, space grey, light oak and a bright blue. */
    const A1_WHITE = 0xf5f5f7, A1_SILVER = 0xd2d4d8, A1_SILVER_LIGHT = 0xe8eaec, A1_SILVER_DARK = 0xa0a4aa, A1_GREY = 0x86868b, A1_SPACE = 0x3a3a3c;
    const A1_OAK = 0xd8b88a, A1_OAK_LIGHT = 0xe8cca0, A1_OAK_DARK = 0xb0905e, A1_BLUE = 0x0071e3;
