        for (let k = 0; k <= r; k++) { const w = k; fill(cx - w, cy - r - 1 + k, w, 1, lit, alpha); fill(cx, cy - r - 1 + k, w + 1, 1, dark, alpha); }
        for (let k = 0; k < r; k++) { const w = r - 1 - k; fill(cx - w, cy + 1 + k, w, 1, low, alpha); fill(cx, cy + 1 + k, w + 1, 1, dark, alpha); }
