      fill(262, 59, 7, 5, berry); fill(263, 58, 5, 1, berry); fill(263, 59, 1, 3, 0xe0606a); fill(268, 59, 1, 5, 0x8a2430);
      fill(264, 57, 3, 1, cream); dot(265, 56, cream);
