      fill(280, 70, 17, 11, metal); fill(280, 70, 17, 1, metalLight); fill(280, 70, 1, 11, metalLight); fill(296, 70, 1, 11, metalDark); fill(280, 80, 17, 1, metalDark);
      dot(284, 77, 0xd8402a); dot(287, 77, 0xe8c878); fill(290, 74, 4, 4, metalDark);
