      fill(265, 78, 26, 11, stone); fill(265, 78, 1, 11, stoneLight); fill(290, 78, 1, 11, stoneDark);
      fill(263, 75, 30, 3, stoneLight); fill(263, 75, 30, 1, 0x8a9098); fill(263, 77, 30, 1, stoneDark);
      // The pulse: slow, quicker when someone is there
      const p = 0.5 + 0.5 * Math.sin(now * (someone ? 1.8 : 0.9));
      // The ring and sign carved in the block's face
      ellipseRing(cx, 84, 6, 4, glow, 0.35 + p * 0.5);
      line(cx, 81, cx, 87, glow, 0.4 + p * 0.5); line(cx, 83, cx - 3, 81, glow, 0.35 + p * 0.45); line(cx, 83, cx + 3, 81, glow, 0.35 + p * 0.45);
      dot(cx, 84, 0xd8fff0, 0.5 + p * 0.5);
      for (const rx of [267, 288]) { dot(rx, 80, stoneLight); dot(rx, 86, stoneDark); }
      // The candles, wavering, with a closed tome and a small bowl between them
      const lit = (someone ? 1.15 : 1) * candlelight(cx * 0.1);
      for (const [px, h, k] of [[268, 5, 0], [273, 3, 1], [283, 4, 2], [288, 6, 3]]) {
        fill(px, 75 - h, 2, h, wax); fill(px + 1, 75 - h, 1, h, waxShade);
        const f = candlelight(k + px * 0.1);
        dot(px, 74 - h, 0xffd85a, Math.min(1, f)); dot(px, 73 - h, 0xff8a3d, 0.6 * f);
        glowAt(px, 72 - h, 5, 4, 0xffb04a, 0.07 * f);
      }
      fill(276, 73, 6, 2, 0x4a2c38); fill(276, 73, 6, 1, 0x6a4252); dot(278, 74, 0xc8a050);
      // The floating sigil above, a ring and a five-pointed star, pulsing
      const sy = 58 + Math.round(Math.sin(now * 0.5));
      ellipseRing(cx, sy, 8, 8, glow, 0.15 + p * 0.3); ellipseRing(cx, sy, 6, 6, glow, 0.1 + p * 0.2);
      const pts = [0, 1, 2, 3, 4].map((k) => [cx + Math.round(Math.cos(-Math.PI / 2 + k * 1.2566) * 6), sy + Math.round(Math.sin(-Math.PI / 2 + k * 1.2566) * 6)]);
      for (let k = 0; k < 5; k++) { const a = pts[k], b = pts[(k + 2) % 5]; line(a[0], a[1], b[0], b[1], glow, 0.25 + p * 0.5); }
