    /** The Brooklyn Knight, the Nets' mascot: a knight in a steel helmet with a white plume and an open visor, carrying a black shield with a pair of white bridge cables; he flexes, waves, dances or spins a ball, the plume nodding as he moves. */
    function drawNetsmascot() {
      const steel = 0xaab0ba, black = 0x16161a, skin = 0xf0c8a0;
      mascotRig({
        salt: 20, moves: ['flex', 'wave', 'dance', 'ball'],
        jersey: black, trim: WHITE, shorts: WHITE, legs: steel, shoe: steel, arm: steel, hand: 0x6e727c,
        front({ cx, y0, st }) {
          // The shield on the left arm, with the bridge's cables
          if (st.left === 'down') {
            const sx = cx - 17, sy = y0 + 18;
            fill(sx, sy, 9, 12, black); fill(sx + 1, sy + 11, 7, 1, black); fill(sx + 3, sy + 12, 3, 1, black); fill(sx, sy, 9, 1, steel); fill(sx, sy, 1, 12, steel); fill(sx + 8, sy, 1, 12, 0x6e727c);
            fill(sx + 2, sy + 3, 1, 5, WHITE); fill(sx + 6, sy + 3, 1, 5, WHITE); dot(sx + 3, sy + 4, WHITE); dot(sx + 4, sy + 5, WHITE); dot(sx + 5, sy + 4, WHITE); fill(sx + 1, sy + 8, 7, 1, WHITE);
          }
        },
        head({ x, y, st }) {
          // The plume, nodding with the dance
          const n = st.move === 'dance' ? (st.wob ? 1 : 0) : 0;
          fill(x - 1 + n, y - 7, 3, 7, WHITE); fill(x + n, y - 9, 3, 3, WHITE); fill(x + 2 + n, y - 8, 2, 4, 0xdde2e8); fill(x - 1, y - 7, 1, 7, 0xdde2e8);
          mascotBlock(x - 8, y, 16, 15, steel); fill(x - 1, y, 2, 15, 0x8a909a, 0.6);
          // The open visor and the face
          fill(x - 6, y + 4, 12, 8, 0x3a3e48); fill(x - 5, y + 5, 10, 6, skin);
          mascotEyes(x, y + 6, 3, st, 0x1f1a1a); mascotMouth(x, y + 9, st, 0x7a3a30);
          fill(x - 8, y + 14, 16, 1, 0x6e727c); dot(x - 7, y + 2, WHITE, 0.8); dot(x - 7, y + 3, WHITE, 0.5);
        },
      });
    }

    /** Boomer the Bobcat, the Pacers' mascot: a spotted tawny bobcat with tufted black-tipped ears, cheek ruffs and a stubby tail in a navy and gold kit; he waves, dances, spins a ball or hops. */
