          mascotBlock(x - 8, y + 1, 16, 13, fur); dot(x - 5, y + 3, spot); dot(x - 4, y + 4, spot); dot(x + 4, y + 3, spot); dot(x + 3, y + 4, spot); fill(x - 1, y + 1, 2, 2, spot);
          // Cheek ruffs and the muzzle
