        front({ cx, y0 }) { fill(cx - 5, y0 + 14, 10, 2, black); fill(cx - 3, y0 + 16, 6, 2, black); fill(cx - 1, y0 + 18, 2, 1, black); dot(cx - 2, y0 + 15, 0xe8c050); },
