          mascotBlock(x - 8, y + 1, 16, 13, fur); fill(x - 1, y + 1, 2, 3, stripe); fill(x - 4, y + 2, 2, 2, stripe); fill(x + 2, y + 2, 2, 2, stripe); fill(x - 8, y + 6, 2, 1, stripe); fill(x + 6, y + 6, 2, 1, stripe);
          mascotBlock(x - 5, y + 7, 10, 7, cream); fill(x - 1, y + 7, 3, 2, 0xe88a8a);
          for (const wy of [9, 11]) { fill(x - 10, y + wy, 3, 1, WHITE, 0.7); fill(x + 7, y + wy, 3, 1, WHITE, 0.7); }
          mascotEyes(x, y + 4, 3, st, 0x1f1a1a, true); dot(x - 4, y + 5, 0xa8c850); dot(x + 3, y + 5, 0xa8c850); mascotMouth(x, y + 11, st, 0x5a2a2a);
