      fill(294 + inhale - (scratch ? 3 : 0), 66 + (scratch ? 4 : 0), 6, 12, B); fill(299 + inhale - (scratch ? 3 : 0), 66 + (scratch ? 4 : 0), 1, 12, BD);
      for (let k = 0; k < 3; k++) dot(295 + k * 2 + inhale - (scratch ? 3 : 0), 78 + (scratch ? 4 : 0), claw);
