      fill(266, 64, 22, 16, oakDark);
      fill(271, 65, 12, 6, 0xf2ead8); for (const ly of [66, 68, 70]) fill(272, ly, 10, 1, 0x8a8070, 0.6);
      for (const sx of [267, 269, 285, 287]) { dot(sx, 66, 0xf2ead8); dot(sx, 69, 0xd8b45a); }
      fill(267, 76, 20, 3, 0xf6f2e8); fill(267, 79, 20, 1, oakDark);
      for (let k = 0; k < 20; k += 3) fill(268 + k, 76, 1, 2, 0x2a2a30);
      if (playing && onBeat()) { const kx = 267 + ((Math.floor(now * 4) * 7) % 19); fill(kx, 77, 2, 2, 0xc8c0b0); }
      // The bench
      fill(264, 86, 26, 2, oak); fill(264, 86, 26, 1, oakLight); fill(266, 88, 1, 5, oakDark); fill(287, 88, 1, 5, oakDark);
      // The notes rising from the pipes while it plays
