      fill(260, 82, 36, 9, lacDark, 0.4); for (const gx of [266, 278, 290]) { dot(gx, 86, gold); dot(gx - 1, 87, gold, 0.6); dot(gx + 1, 87, gold, 0.6); }
      // The stepped pedestal
      fill(266, 74, 24, 4, lacDark); fill(266, 74, 24, 1, gold); fill(269, 70, 18, 4, lac); fill(269, 70, 18, 1, gold);
      // The halo, and the figure: a quiet golden form seated on the lotus, hands resting in its lap
