      fill(cx - 1, 50, 2, 1, gold); fill(cx - 2, 51, 5, 5, gold); dot(cx - 2, 51, goldDark); dot(cx + 2, 51, goldDark); fill(cx - 2, 51, 1, 4, goldLight);
      dot(cx - 3, 52, goldDark); dot(cx + 3, 52, goldDark); fill(cx - 3, 53, 1, 2, goldDark); fill(cx + 3, 53, 1, 2, goldDark);
      fill(cx - 1, 53, 3, 1, goldDark, 0.3);
      fill(cx - 1, 56, 3, 1, goldDark);
      fill(cx - 5, 57, 11, 7, gold); fill(cx - 5, 57, 1, 7, goldLight); fill(cx + 5, 57, 1, 7, goldDark); line(cx - 4, 57, cx + 4, 63, goldDark, 0.45);
      fill(cx - 2, 62, 5, 2, goldLight);
      fill(cx - 7, 64, 15, 3, gold); fill(cx - 7, 64, 1, 3, goldLight); fill(cx + 7, 64, 1, 3, goldDark); fill(cx - 7, 66, 15, 1, goldDark);
      fill(cx - 8, 67, 17, 3, pink); for (let k = -8; k <= 8; k += 2) dot(cx + k, 67, pinkLight); fill(cx - 8, 69, 17, 1, pinkDark);
      // On the table: the lamps, the oranges, the lotuses, the incense
