      if (isNight) glowLate(() => { glowAt(278, 68, 22, 14, 0xffd890, 0.12); });
      // The bamboo shadows on the paper
      const t = (now + 2) % 12, sway = t < 2 ? Math.floor(t * 3) % 2 : 0;
