      for (const [lx, ly] of [[259, 60], [261, 66], [262, 72], [263, 60]]) { line(lx, ly, lx + 4 + sway, ly - 2, shade, 0.7); line(lx, ly + 1, lx - 3 - sway, ly - 1, shade, 0.6); }
