      fill(275, 86, 11, 4, cushion); fill(276, 85, 9, 1, cushion); fill(276, 85, 9, 1, shaded(cushion, 1.3)); fill(275, 89, 11, 1, shaded(cushion, 0.8));
      // The little stone lantern, a light inside at night
      fill(296, 88, 6, 5, stone); fill(295, 87, 8, 1, stoneDark); fill(297, 82, 4, 5, stone); fill(298, 83, 2, 2, isNight ? 0xffe0a0 : 0x4a4e48);
      fill(295, 80, 8, 2, stoneDark); dot(299, 79, stone);
      if (isNight) glowLate(() => { glowAt(299, 84, 4, 3, 0xffc070, 0.2); fill(298, 83, 2, 2, 0xffe8b0); });
