      fill(258, 50, 40, 10, steel); fill(258, 50, 40, 1, steelLight); fill(260, 52, 36, 6, 0x2a1e1a);
      const sal = () => { for (let k = 0; k < 4; k++) fill(262 + k * 9, 53, 7, 1, 0xff5a2a, 0.9); };
      sal(); fill(258, 60, 40, 1, steelDark);
