      // The pans: a sauté pan, a sauce pot, a copper pan
      fill(253, 66, 10, 3, iron); fill(253, 66, 10, 1, 0x4a4a52); line(263, 67, 268, 64, iron);
      fill(266, 61, 9, 8, steel); fill(266, 61, 1, 8, steelLight); fill(274, 61, 1, 8, steelDark); fill(266, 61, 9, 1, steelDark);
      fill(277, 65, 6, 4, copper); fill(277, 65, 6, 1, 0xe8a060); line(283, 66, 286, 64, 0x8a4a22);
      for (let k = 0; k < 3; k++) { const ph = (now * 0.5 + k / 3) % 1; dot(269 + k * 2 + Math.round(Math.sin(ph * 6)), 60 - Math.round(ph * 7), WHITE, 0.5 * (1 - ph)); }
