      for (let y = 47, r = 0; y < 92; y += 4, r++) { fill(250, y + 3, 56, 1, mortar); for (let x = 250 + (r % 2) * 5; x < 306; x += 10) fill(x, y, 1, 3, mortar); }
      fill(249, 91, 58, 3, 0x2a2238); fill(249, 91, 58, 1, 0x4a4058);
      // The splashes behind the mask, and their drips
      disc(262, 58, 7, 0xf28fb0, 0.85); disc(294, 62, 7, 0x30c8d8, 0.85); disc(272, 80, 6, 0xf2d35b, 0.85);
      for (const [dx, len, c] of [[259, 9, 0xf28fb0], [297, 12, 0x30c8d8], [270, 7, 0xf2d35b], [265, 5, 0xf28fb0]]) fill(dx, dx === 270 ? 85 : 64, 1, len, c, 0.75);
