      for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; line(cx, cy, cx + Math.round(Math.cos(a) * 10), cy + Math.round(Math.sin(a) * 12), red, 0.85); }
      ellipseRing(cx, cy, 5, 6, red, 0.85); ellipseRing(cx, cy, 8.5, 10, red, 0.85);
      const t = (now + 3) % 12, narrow = t < 1 ? 2 : 0;
      for (const s of [-1, 1]) {
        const ex = cx + s * 5;
        fill(ex - 3, cy - 4 + narrow, 6, 5 - narrow, WHITE); fill(ex - 3, cy - 4 + narrow, 6, 1, ink);
        dot(s < 0 ? ex - 3 : ex + 2, cy - 4 + narrow, ink); dot(s < 0 ? ex + 2 : ex - 3, cy + 1, ink);
      }
      // The tag under it, in yellow
      for (let k = 0; k < 14; k++) dot(284 + k, 86 + Math.round(Math.sin(k * 1.1) * 1.5), 0xf2d35b);
