      for (let k = 0; k < 4; k++) ellipseRing(cx, cy, 13 - k * 3, 13 - k * 3, cols[k], 0.6);
      for (let k = 0; k < 8; k++) { const a = ((k * 2 + spin) / 16) * Math.PI * 2, r = 4 + (k % 3) * 4; dot(cx + Math.round(Math.cos(a) * r), cy + Math.round(Math.sin(a) * r), cols[k % 4]); }
