      for (let k = 0; k < 8; k++) { const a = (k / 8) * Math.PI * 2; dot(cx + Math.round(Math.cos(a) * 17), cy + Math.round(Math.sin(a) * 17), 0xf2d35b); }
      // The base and the control box with its cable
      fill(cx - 12, 80, 24, 4, steelDark); fill(cx - 15, 84, 30, 9, steel); fill(cx - 15, 84, 30, 1, steelLight); fill(cx - 15, 92, 30, 1, steelDark);
      for (let k = 0; k < 4; k++) dot(cx - 11 + k * 7, 88, Math.floor(now * 2 + k) % 3 ? 0x5ad86a : 0xd8202a);
      fill(297, 82, 8, 11, steelDark); fill(297, 82, 8, 1, steel); fill(298, 84, 6, 3, 0x1a1030); dot(299 + Math.floor(now * 3) % 4, 85, 0x30e0f0);
