      line(276, 56, 268, 46, 0x8a8e96); line(280, 56, 290, 47, 0x8a8e96); dot(268, 46, 0xb8bcc4); dot(290, 47, 0xb8bcc4); fill(276, 54, 5, 2, 0x3a3a42);
      fill(261, 59, 28, 18, 0x1a1a1e);
