      fill(253, 72, 38, 4, gold); fill(253, 72, 38, 1, goldLight); fill(253, 75, 38, 1, goldDark);
      // The laser on its arm
      fill(296, 48, 8, 46, steelDark); fill(296, 48, 1, 46, steel); fill(270, 48, 28, 4, steelDark); fill(270, 48, 28, 1, steel);
      fill(266, 50, 8, 8, steel); fill(266, 50, 8, 1, steelLight); fill(268, 58, 4, 3, 0x3a3a42); dot(269, 61, 0xff3a2a);
