      const someone = atCorner(0);
      const steel = 0x55596a, steelLight = 0x7a7e8c, steelDark = 0x3a3e4a, brass = 0xc8a050, brassLight = 0xe8c878, white = 0xd8dce4, sky = 0x0e1430;
