      if (someone) dot(262, 70, WHITE, 0.6);
      if (isNight) glowLate(() => { for (let k = 0; k < 6; k++) dot(289 + hash(k, 2) % 4, 41 + k * 2, 0xf6f6f2, 0.9); glowAt(291, 46, 5, 9, 0xbfc8e8, 0.12); });
