      fill(sx - 2, sy - 4, 4, 24, leather); fill(sx + 32, sy - 4, 4, 24, leather); fill(sx - 2, sy - 4, 1, 24, leatherLight);
      fill(sx, sy + 14, 34, 6, leatherDark);
      for (let r = 0; r < 2; r++) for (let c = 0; c < 5; c++) dot(sx + 5 + c * 6, sy - 3 + r * 5, leatherDark);
      fill(sx + 2, sy + 20, 2, 2, wood); fill(sx + 30, sy + 20, 2, 2, wood);
      fill(sx + 6, sy + 2, 8, 6, 0x8a3a3a); fill(sx + 6, sy + 2, 8, 1, 0xa84a4a);
      const gx = 296, gy = 74;
      fill(gx - 4, gy + 12, 8, 2, wood); fill(gx - 1, gy + 6, 2, 8, wood);
      line(gx - 4, gy + 6, gx - 1, gy + 13, wood); line(gx + 4, gy + 6, gx + 1, gy + 13, wood);
      disc(gx, gy, 7, globe);
      fill(gx - 3, gy - 2, 4, 3, globeLand); fill(gx + 1, gy + 1, 3, 3, globeLand, 0.9);
