          p(4, -2, 1, 1, PALETTE.eye);
          p(-6, -1, 3, 1, dark);
          p(-2, 0 - step, 1, 1, dark);
          p(2, -1 + step, 1, 1, dark);
          p(-2, -3 + step, 1, 1, dark);
          p(2, -3, 1, 1, dark);
