          const spits = fired && Math.hypot(fired.position.x - x, fired.position.y - y) < 120;
          if (spits) pet.facing = fired.position.x > x ? 1 : -1;
          const chew = pose === 'chew' || spits ? Math.floor(now * 2.5) % 2 : 0;
