          p(-3, -1, 7 + stretch, 1, body);
          p(3 + stretch, -2, 2, 1, body);
          p(4 + stretch, -4, 1, 2, body);
          dot(pet.facing > 0 ? x + 4 + stretch : x - 4 - stretch, y - 5, PALETTE.eye);
